from flask import Flask, Blueprint

app = Flask(__name__)

admin_bp = Blueprint('admin', __name__, url_prefix='/admin')

@admin_bp.route('/dashboard')
def dashboard():
    return 'Admin access granted'

app.register_blueprint(admin_bp)

@app.route('/<path:path>')
def catch_all(path):
    return 'Not Found'

if __name__ == '__main__':
    app.run(debug=True)
